package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.Bundle;import android.view.*;import java.util.concurrent.atomic.*;
public class PlayerStyleTest extends Instrumentation {
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    View find(View v,String desc){if(desc.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),desc);if(found!=null)return found;}return null;}
    void await(java.util.function.BooleanSupplier condition,String error)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+30000;while(android.os.SystemClock.elapsedRealtime()<end){AtomicBoolean done=new AtomicBoolean();ui(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(50);}throw new AssertionError(error);}
    void screenshot(String filename)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),filename))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;try{activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","player_style_qa").putExtra("book_name","我爱听书 · 播放界面").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.offlineReady,"voice not ready");ui(()->{StringBuilder text=new StringBuilder();for(int c=1;c<=2;c++){text.append("第").append(c).append("章 山间的风\n");for(int i=0;i<20;i++)text.append("风吹过山间，书页轻轻翻动。戴上耳机，让每一段文字都有声音。\n\n");}a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.chapter=0;a.position=0;a.readingLanguage="";a.systemVoiceKey="";a.offlineVoice=1000;a.setReadingMode(false);a.showPosition(true);a.startReading();});await(()->a.playing&&a.status.getText().toString().startsWith("离线连续朗读"),"playback did not start");
        ui(()->{check(a.play instanceof PlayerToggle,"not geometric play button");int[] center=new int[2],root=new int[2],mode=new int[2];a.play.getLocationOnScreen(center);a.root.getLocationOnScreen(root);a.playbackMode.getLocationOnScreen(mode);check(Math.abs((center[0]+a.play.getWidth()/2)-(root[0]+a.root.getWidth()/2))<=2,"play not centered");check(mode[0]>=center[0]+a.play.getWidth(),"mode overlaps play");check(a.play.getWidth()==a.play.getHeight(),"play not circular");check(find(a.root,"上一章")!=null&&find(a.root,"下一章")!=null,"chapter icons missing");check(a.play.getContentDescription().equals("暂停朗读"),"playing action description wrong");});screenshot("player-style-playing.png");
        ui(()->{a.play.performClick();check(!a.playing&&a.play.getContentDescription().equals("开始朗读"),"pause button did not pause");});Thread.sleep(200);screenshot("player-style-paused.png");ui(()->{find(a.root,"下一章").performClick();check(a.chapter==1,"next chapter failed");find(a.root,"上一章").performClick();check(a.chapter==0,"previous chapter failed");boolean old=a.loopPlayback;a.playbackMode.performClick();check(a.loopPlayback!=old,"mode switch failed");a.playbackMode.performClick();a.night=true;a.theme();});screenshot("player-style-night.png");result.putString("result","PASS: centered circular play/pause; chapter icons and navigation; right-side mode; playback/pause; day/night screenshots");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}getTargetContext().getSharedPreferences("reader_player_style_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
